package org.apache.commons.math3.dfp;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_17_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        DfpField field = new DfpField(10);
        Dfp finiteNumber = field.newDfp(123.456);
        Dfp result = finiteNumber.multiply(-1);

        // The expected behavior is that multiplying a positive number by -1 should result in the negative of that number
